fn fibonacci(n: usize) -> Vec<i32> {
    // Assume n >= 2
    
    // Initialize a vector with capacity n to avoid resizing
    let mut fib_vec = Vec::with_capacity(n);
    
    // Base cases
    fib_vec.push(0);  // F(0)
    fib_vec.push(1);  // F(1)
    
    // Compute Fibonacci values from index 2 to n-1
    for i in 2..n {
        // Safe to unwrap as we always have at least two elements in fib_vec
        let next_val = fib_vec[i - 1] + fib_vec[i - 2];
        fib_vec.push(next_val);
    }
    
    fib_vec
}